import RNA, random, multiprocessing as mp, time, sys

target = open('/tmp/rna_target_exact.txt').read().strip()
n = len(target)
assert len(target) == 396

pairs = {}
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop(); pairs[j] = i; pairs[i] = j

# rational all-GC starter
base = ['A'] * n
for i in range(n):
    if target[i] == '(':
        base[i] = 'G'; base[pairs[i]] = 'C'
base = ''.join(base)


def fold_dist(seq):
    fc = RNA.fold_compound(seq)
    ss, e = fc.mfe()
    return RNA.bp_distance(ss, target), ss, e


def worker(seed):
    rng = random.Random(seed)
    cur = list(base)
    # perturb the lone-pair flank region heavily at start
    cur_d, cur_ss, _ = fold_dist(''.join(cur))
    best_seq = ''.join(cur)
    best_d = cur_d
    # mutation budget: focus on positions 0-9 and 380-395, but occasionally global
    flank_pos = list(range(0, 10)) + list(range(380, 396))
    all_pos = list(range(n))
    iters = 4000
    for it in range(iters):
        # pick positions to mutate
        if rng.random() < 0.7:
            num = rng.randint(1, 3)
            pos = rng.sample(flank_pos, num)
        else:
            num = rng.randint(1, 4)
            pos = rng.sample(all_pos, num)
        cand = cur[:]
        for p in pos:
            cand[p] = rng.choice('ACGU')
        cand_s = ''.join(cand)
        d, ss, e = fold_dist(cand_s)
        if d <= cur_d:
            # accept; prefer lower distance, allow equal for plateau walk
            cur = cand; cur_d = d; cur_ss = ss
            if d < best_d:
                best_d = d; best_seq = cand_s
                if d == 0:
                    return (0, best_seq)
        else:
            # SA accept with small prob
            if rng.random() < 0.05:
                cur = cand; cur_d = d
    return (best_d, best_seq)


def main():
    t0 = time.time()
    N = 256
    with mp.Pool(N) as p:
        results = p.map(worker, range(N))
    results.sort(key=lambda x: x[0])
    best_d, best_seq = results[0]
    print("best dist", best_d, "elapsed", round(time.time() - t0, 1))
    print("best seq", best_seq)
    # save
    if best_seq:
        open('/tmp/rna_sa_best.txt', 'w').write(best_seq)
    # print top few
    for d, s in results[:5]:
        print("  d", d, s[:40], "...")


if __name__ == '__main__':
    main()

