import RNA, random, multiprocessing as mp, time, signal, sys

target = open('/tmp/rna_target_exact.txt').read().strip()
n = len(target)
assert len(target) == 396

# Build a structure-aware template init (not all-GC, mixed) per memory §7
pairs = {}
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop(); pairs[j] = i; pairs[i] = j

# mixed pair assignment: G-C, C-G, A-U, U-A, G-U varied per stem to avoid coaxial merge
import random as _r
_r.seed(123)
pair_choices = [('G','C'),('C','G'),('G','C'),('C','G'),('A','U'),('U','A'),('G','U')]

def make_template(seed):
    rng = random.Random(seed)
    seq = ['A'] * n
    for i in range(n):
        if target[i] == '(':
            pa = rng.choice(pair_choices)
            seq[i] = pa[0]; seq[pairs[i]] = pa[1]
    # heterogeneous flanks for unpaired positions near lone pair (0,390): positions 1-4, 386-389
    for p in [1,2,3,4,386,387,388,389]:
        seq[p] = rng.choice('ACGU')
    return ''.join(seq)

def dist(seq):
    fc = RNA.fold_compound(seq); ss, e = fc.mfe()
    return RNA.bp_distance(ss, target), ss, e

def worker(seed):
    rng = random.Random(seed)
    deadline = time.time() + 150  # per-worker budget
    best_d = 999; best_seq = None
    tries = 0
    while time.time() < deadline:
        tries += 1
        # warm-start from a template 70% of the time, random 30%
        if rng.random() < 0.7:
            start = make_template(seed * 1000 + tries)
        else:
            start = ''.join(rng.choice('ACGU') for _ in range(n))
        try:
            seq, d = RNA.inverse_fold(start, target)
        except Exception:
            continue
        if d == 0:
            # verify
            ss, _ = RNA.fold_compound(seq).mfe()
            if ss == target:
                return (0, seq, tries)
        if d < best_d:
            best_d = d; best_seq = seq
    return (best_d, best_seq, tries)

def main():
    t0 = time.time()
    N = 240  # leave some cores free
    with mp.Pool(N) as p:
        for r in p.imap_unordered(worker, range(N)):
            d, seq, tries = r
            if d == 0 and seq:
                print("SOLVED after", tries, "tries, elapsed", round(time.time()-t0,1), flush=True)
                print("SEQ", seq, flush=True)
                open('/tmp/rna_solved.txt', 'w').write(seq)
                p.terminate()
                return
            else:
                print("worker best d", d, "tries", tries, "elapsed", round(time.time()-t0,1), flush=True)
    # none solved
    print("NO SOLVE, elapsed", round(time.time()-t0,1), flush=True)

if __name__ == '__main__':
    main()
